// Compare data for ToolStep /compare/ pages.
// 50 product comparisons across hardware, software, and productivity categories.

export interface CompareProduct {
  name: string;
  brand: string;
  price: number;
  rating: number;
  pros: string[];
  cons: string[];
}

export interface CompareSpec {
  label: string;
  productA: string;
  productB: string;
  winner: 'A' | 'B' | 'tie';
}

export interface CompareFaq {
  question: string;
  answer: string;
}

/**
 * Editorial decision content rendered on a compare page when present.
 * All fields are optional so legacy entries render exactly as before.
 * Content added here is per-entry editorial analysis — the template only
 * provides structure, never the substance.
 */
export interface CompareDecisionFactor {
  /** One sentence naming the factor that should change a buyer's choice. */
  factor: string;
  /** Why it matters, and what each product actually does on this factor. */
  contextA: string;
  contextB: string;
  /** When this difference matters (and when it does not). */
  whenItMatters: string;
}

export interface CompareScenarioAnalysis {
  scenario: string;
  verdict: string; // 'A' | 'B' | 'tie'
  /** Who this scenario represents (not the product name). */
  who: string;
  reason: string;
}

/** How this comparison was produced. Aligned with /how-we-test/. */
export type CompareEvidenceLabel =
  | 'documentation-analysis'
  | 'hands-on-testing';

export interface CompareEditorial {
  /** One short decision-oriented summary shown near the top. */
  decisionSummary: string;
  /** The 3-6 factors that actually change the decision. */
  decisionFactors: CompareDecisionFactor[];
  /** Who should pick A / B and who should not. */
  bestForA: string;
  bestForB: string;
  notForA: string;
  notForB: string;
  /** 3+ real-world scenarios with reasons. */
  scenarios: CompareScenarioAnalysis[];
  /** Evidence level. 'documentation-analysis' never claims hands-on testing. */
  evidenceLabel: CompareEvidenceLabel;
  /** Optional note shown in place of a fabricated testing claim. */
  evidenceNote?: string;
}

export interface CompareEntry {
  slug: string;
  title: string;
  category: string;
  color: string;
  description: string;
  productA: CompareProduct;
  productB: CompareProduct;
  quickWinner: 'A' | 'B' | 'tie';
  quickWinnerReason: string;
  specs: CompareSpec[];
  whoWins: { scenario: string; winner: 'A' | 'B' | 'tie' }[];
  faqs: CompareFaq[];
  relatedReviews: string[];
  lastUpdated: string;
  testingDuration: string;
  authorSlug: string;
  /** Optional editorial decision content (Phase 2 enhancement). */
  editorial?: CompareEditorial;
}

